def transform(grid):
    # Restore the 8 rectangle from its reflected counterpart. Most examples
    # use the task's 32-cell reference axis (coordinate sum 31); at a clipped
    # edge, fall back to reflection within the visible 30-cell grid.
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not cells:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    out = [row[:] for row in grid]
    candidates = []
    for axis in (31, w - 1):
        cs = [axis-c for c in range(c0, c1+1)]
        if min(cs) >= 0 and max(cs) < w and all(grid[r][c] != 8 for r in range(r0,r1+1) for c in cs):
            candidates.append(('col', axis))
    for axis in (31, h - 1):
        rs = [axis-r for r in range(r0, r1+1)]
        if min(rs) >= 0 and max(rs) < h and all(grid[r][c] != 8 for r in rs for c in range(c0,c1+1)):
            candidates.append(('row', axis))
    for axis in (31, w - 1):
        cs = [axis-c for c in range(c0, c1+1)]
        if min(cs) >= 0 and max(cs) < w and all(grid[r][c] != 8 for r in range(r0,r1+1) for c in cs):
            candidates.append(('col', axis))
    if not candidates:
        return [out[r][c0:c1+1] for r in range(r0,r1+1)]
    direction, axis = candidates[0]
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            if direction == 'row':
                out[r][c] = grid[axis-r][c]
            else:
                out[r][c] = grid[r][axis-c]
    return [out[r][c0:c1+1] for r in range(r0,r1+1)]

